{"witnessCode": "import { describe, it } from 'node:test'; import assert from 'node:assert/strict'; import normalizeUrl from '../index.js';

describe('keepQueryParameters empty array', () => {
  it('should keep query parameters when keepQueryParameters is empty array (base behavior)', () => {
    const url = 'https://example.com?foo=1&bar=2';
    const opts = { keepQueryParameters: [] };
    const result = normalizeUrl(url, opts);
    assert.ok(result.includes('foo=1'), 'foo parameter missing');
    assert.ok(result.includes('bar=2'), 'bar parameter missing');
    assert.ok(result.includes('?'), 'query string missing');
  });
});"}
